WITH c_rows AS (
    SELECT cds, `AvgScrMath`
    FROM c_cols
    WHERE `AvgScrMath` IS NOT NULL AND `AvgScrMath` > 400
)
SELECT * FROM c_rows;

WITH t_join AS (
    SELECT r.cds, f.`Charter Funding Type`
    FROM c_rows r
    INNER JOIN frpm f ON r.cds = f.`CDSCode`
)
SELECT * FROM t_join;

WITH final_count AS (
    SELECT COUNT(*) AS answer
    FROM t_join
)
SELECT * FROM final_count;

WITH t_funding_types AS (
    SELECT `Charter Funding Type`
    FROM t_join
)
SELECT * FROM t_funding_types;

WITH c_rows AS (
    SELECT cds, `AvgScrRead`
    FROM c_cols
    WHERE `AvgScrRead` IS NOT NULL
)
SELECT * FROM c_rows;

WITH t_join AS (
    SELECT r.cds, r.`AvgScrRead`, s.`Phone`
    FROM c_rows r
    INNER JOIN schools s ON r.cds = s.`CDSCode`
)
SELECT * FROM t_join;

WITH t_agg AS (
    SELECT cds, MIN(`AvgScrRead`) AS min_avg_scr_read
    FROM t_join
    GROUP BY cds
)
SELECT * FROM t_agg;

WITH t_final AS (
    SELECT t.cds, t.`Phone`
    FROM t_agg a
    INNER JOIN t_join t ON a.cds = t.cds
    WHERE a.min_avg_scr_read = (
        SELECT MIN(min_avg_scr_read)
        FROM t_agg
    )
)
SELECT * FROM t_final;

WITH final_answer AS (
    SELECT `Phone`
    FROM t_final
)
SELECT * FROM final_answer;

WITH c_cols AS (
    SELECT c.client_id, c.gender, c.district_id, d.A11
    FROM client c
    JOIN district d ON c.district_id = d.district_id
)
SELECT * FROM c_cols;

WITH c_rows AS (
    SELECT client_id, gender, district_id, A11
    FROM c_cols
    WHERE gender = 'M' AND A11 > 8000
)
SELECT * FROM c_rows;

WITH t_join AS (
    SELECT c.client_id, c.district_id, d.A3
    FROM c_rows c
    JOIN district d ON c.district_id = d.district_id
)
SELECT * FROM t_join;

WITH t_rows AS (
    SELECT client_id
    FROM t_join
    WHERE A3 = 'North Bohemia'
)
SELECT * FROM t_rows;

WITH c_final AS (
    SELECT COUNT(*) AS answer
    FROM c_fuzzy
)
SELECT * FROM c_final;
